//! Process configuration. Decode fixed-size public identifiers exactly once at startup.
//!
//! Required environment variables:
//! - LASTRO_API_BIND, e.g. `127.0.0.1:8080`;
//! - LASTRO_DATABASE_URL;
//! - LASTRO_AGENT_TOKEN (demo transport authentication; secret, never logged);
//! - LASTRO_SOLANA_RPC_URL;
//! - LASTRO_DEPLOYMENT_ID_HEX (32 bytes / 64 lowercase hex chars);
//! - LASTRO_STATION_PUBKEY_HEX (SEC1 compressed P-256, 33 bytes / 66 lowercase hex chars);
//! - LASTRO_PROGRAM_ID (base58 Solana address generated by the real program keypair).
//!
//! Optional:
//! - LASTRO_OPERATOR_TOKEN (>= 32 chars) enables the operational v2 routes;
//! - LASTRO_PRIORITY_FEE_MICRO_LAMPORTS, compute-unit price appended to prepared transactions
//!   (max 1_000_000); unset keeps the exact two-instruction envelope;
//! - LASTRO_CORS_ALLOWED_ORIGINS, comma-separated `scheme://host[:port]` origins. Unset keeps
//!   the permissive development policy; public deployments must set it.
//! - LASTRO_SPONSOR_KEYPAIR_PATH, Solana keypair JSON of the platform fee sponsor (secret,
//!   kept outside the repository). Unset keeps every transaction paid by its own signer.
//!   With it: LASTRO_SPONSOR_MAX_LAMPORTS_PER_TX, LASTRO_SPONSOR_DAILY_LAMPORTS_PER_SIGNER and
//!   LASTRO_SPONSOR_DAILY_LAMPORTS_TOTAL bound what the sponsor may spend.
//! - LASTRO_ORG_KEY_ENCRYPTION_KEY_FILE (preferred) or LASTRO_ORG_KEY_ENCRYPTION_KEY_HEX, the
//!   32-byte master key sealing organization wallets (S2; secret, held outside the database,
//!   the file holding 64 lowercase hex characters). Unset disables managed organization wallets.
//! - LASTRO_OTP_DELIVERY=log writes one-time login codes to the service log. Development only:
//!   it is refused whenever LASTRO_CORS_ALLOWED_ORIGINS is set (a public deployment). Unset
//!   disables one-time-code login until an e-mail or SMS provider is wired.
//!
//! No default may silently point execution at the wrong deployment.

use std::{env, net::SocketAddr, path::PathBuf, str::FromStr};

use axum::http::HeaderValue;

use lastro_protocol::{crypto::derive_station_id, ids::DeploymentId};
use solana_pubkey::Pubkey;

use crate::{error::ApiError, sponsor::SponsorLimits};

#[derive(Clone)]
pub struct AppConfig {
    pub bind_addr: SocketAddr,
    pub database_url: String,
    pub agent_token: String,
    pub operator_token: Option<String>,
    pub solana_rpc_url: String,
    pub deployment_id: DeploymentId,
    pub station_pubkey33: [u8; 33],
    pub lastro_program_id: String,
    /// Empty means any origin (development only).
    pub cors_allowed_origins: Vec<HeaderValue>,
    pub priority_fee_micro_lamports: Option<u64>,
    /// Fee sponsor keypair file; `None` keeps the deployment self-paid.
    pub sponsor_keypair_path: Option<PathBuf>,
    pub sponsor_limits: SponsorLimits,
    /// Master key of the organization key vault; `None` disables managed wallets.
    pub org_key_encryption_key: Option<[u8; 32]>,
    /// One-time login codes are written to the log (development delivery).
    pub otp_log_delivery: bool,
}

impl AppConfig {
    pub fn from_env() -> Result<Self, ApiError> {
        Self::from_lookup(|name| env::var(name).ok())
    }

    pub fn from_lookup<F>(mut lookup: F) -> Result<Self, ApiError>
    where
        F: FnMut(&str) -> Option<String>,
    {
        fn required<F>(lookup: &mut F, name: &'static str) -> Result<String, ApiError>
        where
            F: FnMut(&str) -> Option<String>,
        {
            let value = lookup(name).ok_or_else(|| ApiError::Config(format!("missing {name}")))?;
            if value.trim().is_empty() {
                return Err(ApiError::Config(format!("{name} must not be empty")));
            }
            Ok(value)
        }

        fn hex_array<const N: usize>(name: &'static str, value: &str) -> Result<[u8; N], ApiError> {
            if value.len() != N * 2 || value != value.to_ascii_lowercase() {
                return Err(ApiError::Config(format!(
                    "{name} must be exactly {N} bytes of lowercase hexadecimal"
                )));
            }
            let bytes = hex::decode(value).map_err(|_| {
                ApiError::Config(format!("{name} must be valid lowercase hexadecimal"))
            })?;
            bytes
                .try_into()
                .map_err(|_| ApiError::Config(format!("{name} must decode to exactly {N} bytes")))
        }

        let bind_addr = required(&mut lookup, "LASTRO_API_BIND")?
            .parse()
            .map_err(|_| ApiError::Config("LASTRO_API_BIND must be a socket address".into()))?;

        let database_url = required(&mut lookup, "LASTRO_DATABASE_URL")?;
        if !(database_url.starts_with("postgres://") || database_url.starts_with("postgresql://")) {
            return Err(ApiError::Config(
                "LASTRO_DATABASE_URL must use postgres:// or postgresql://".into(),
            ));
        }

        let agent_token = required(&mut lookup, "LASTRO_AGENT_TOKEN")?;
        if agent_token.len() < 32 {
            return Err(ApiError::Config(
                "LASTRO_AGENT_TOKEN must contain at least 32 characters".into(),
            ));
        }

        let operator_token =
            lookup("LASTRO_OPERATOR_TOKEN").filter(|value| !value.trim().is_empty());
        if operator_token
            .as_ref()
            .is_some_and(|value| value.len() < 32)
        {
            return Err(ApiError::Config(
                "LASTRO_OPERATOR_TOKEN must contain at least 32 characters".into(),
            ));
        }

        let solana_rpc_url = required(&mut lookup, "LASTRO_SOLANA_RPC_URL")?;
        let parsed_rpc = reqwest::Url::parse(&solana_rpc_url).map_err(|_| {
            ApiError::Config("LASTRO_SOLANA_RPC_URL must be an absolute http(s) URL".into())
        })?;
        if !matches!(parsed_rpc.scheme(), "http" | "https") {
            return Err(ApiError::Config(
                "LASTRO_SOLANA_RPC_URL must use http or https".into(),
            ));
        }

        let deployment_id = hex_array::<32>(
            "LASTRO_DEPLOYMENT_ID_HEX",
            &required(&mut lookup, "LASTRO_DEPLOYMENT_ID_HEX")?,
        )?;
        let station_pubkey33 = hex_array::<33>(
            "LASTRO_STATION_PUBKEY_HEX",
            &required(&mut lookup, "LASTRO_STATION_PUBKEY_HEX")?,
        )?;
        derive_station_id(&station_pubkey33).map_err(|_| {
            ApiError::Config(
                "LASTRO_STATION_PUBKEY_HEX must be a valid compressed P-256 public key".into(),
            )
        })?;

        let lastro_program_id = required(&mut lookup, "LASTRO_PROGRAM_ID")?;
        Pubkey::from_str(&lastro_program_id).map_err(|_| {
            ApiError::Config("LASTRO_PROGRAM_ID must be a valid Solana address".into())
        })?;

        let cors_allowed_origins = lookup("LASTRO_CORS_ALLOWED_ORIGINS")
            .map(|value| parse_origins(&value))
            .transpose()?
            .unwrap_or_default();

        let priority_fee_micro_lamports = lookup("LASTRO_PRIORITY_FEE_MICRO_LAMPORTS")
            .filter(|value| !value.trim().is_empty())
            .map(|value| {
                value
                    .parse::<u64>()
                    .ok()
                    .filter(|price| (1..=MAX_PRIORITY_FEE_MICRO_LAMPORTS).contains(price))
                    .ok_or_else(|| {
                        ApiError::Config(format!(
                            "LASTRO_PRIORITY_FEE_MICRO_LAMPORTS must be an integer in 1..={MAX_PRIORITY_FEE_MICRO_LAMPORTS}"
                        ))
                    })
            })
            .transpose()?;

        let sponsor_keypair_path = lookup("LASTRO_SPONSOR_KEYPAIR_PATH")
            .filter(|value| !value.trim().is_empty())
            .map(PathBuf::from);
        let mut lamports = |name: &'static str, default: u64| -> Result<u64, ApiError> {
            lookup(name)
                .filter(|value| !value.trim().is_empty())
                .map(|value| {
                    value
                        .parse::<u64>()
                        .ok()
                        .filter(|amount| *amount > 0)
                        .ok_or_else(|| {
                            ApiError::Config(format!("{name} must be a positive integer"))
                        })
                })
                .transpose()
                .map(|value| value.unwrap_or(default))
        };
        let sponsor_limits = SponsorLimits {
            max_lamports_per_transaction: lamports(
                "LASTRO_SPONSOR_MAX_LAMPORTS_PER_TX",
                SponsorLimits::DEFAULT_MAX_LAMPORTS_PER_TRANSACTION,
            )?,
            daily_lamports_per_signer: lamports(
                "LASTRO_SPONSOR_DAILY_LAMPORTS_PER_SIGNER",
                SponsorLimits::DEFAULT_DAILY_LAMPORTS_PER_SIGNER,
            )?,
            daily_lamports_total: lamports(
                "LASTRO_SPONSOR_DAILY_LAMPORTS_TOTAL",
                SponsorLimits::DEFAULT_DAILY_LAMPORTS_TOTAL,
            )?,
        };

        let key_hex = lookup("LASTRO_ORG_KEY_ENCRYPTION_KEY_HEX").filter(|v| !v.trim().is_empty());
        let key_file =
            lookup("LASTRO_ORG_KEY_ENCRYPTION_KEY_FILE").filter(|v| !v.trim().is_empty());
        let org_key_encryption_key = match (key_hex, key_file) {
            (Some(_), Some(_)) => {
                return Err(ApiError::Config(
                    "set only one of LASTRO_ORG_KEY_ENCRYPTION_KEY_HEX and LASTRO_ORG_KEY_ENCRYPTION_KEY_FILE"
                        .into(),
                ));
            }
            (Some(hex), None) => Some(hex_array::<32>("LASTRO_ORG_KEY_ENCRYPTION_KEY_HEX", &hex)?),
            (None, Some(path)) => {
                let text = std::fs::read_to_string(&path).map_err(|_| {
                    ApiError::Config("LASTRO_ORG_KEY_ENCRYPTION_KEY_FILE cannot be read".into())
                })?;
                Some(hex_array::<32>(
                    "LASTRO_ORG_KEY_ENCRYPTION_KEY_FILE",
                    text.trim(),
                )?)
            }
            (None, None) => None,
        };
        if org_key_encryption_key.is_some_and(|key| key.iter().all(|byte| *byte == key[0])) {
            return Err(ApiError::Config(
                "the organization master key must be 32 random bytes".into(),
            ));
        }
        let otp_log_delivery = match lookup("LASTRO_OTP_DELIVERY")
            .filter(|value| !value.trim().is_empty())
            .as_deref()
        {
            None => false,
            Some("log") if !cors_allowed_origins.is_empty() => {
                return Err(ApiError::Config(
                    "LASTRO_OTP_DELIVERY=log is development-only and refused when LASTRO_CORS_ALLOWED_ORIGINS is set"
                        .into(),
                ));
            }
            Some("log") => true,
            Some(_) => {
                return Err(ApiError::Config(
                    "LASTRO_OTP_DELIVERY must be unset or `log`".into(),
                ));
            }
        };

        Ok(Self {
            bind_addr,
            database_url,
            agent_token,
            operator_token,
            solana_rpc_url,
            deployment_id,
            station_pubkey33,
            lastro_program_id,
            cors_allowed_origins,
            priority_fee_micro_lamports,
            sponsor_keypair_path,
            sponsor_limits,
            org_key_encryption_key,
            otp_log_delivery,
        })
    }
}

/// Priority fee = 200_000 units x price / 1_000_000. This cap bounds it to 200_000 lamports
/// (0.0002 SOL) per transaction, the same bound the browser enforces before signing.
pub const MAX_PRIORITY_FEE_MICRO_LAMPORTS: u64 = 1_000_000;

/// Accepts only bare origins so a typo cannot silently widen or break the CORS policy.
fn parse_origins(value: &str) -> Result<Vec<HeaderValue>, ApiError> {
    let invalid = || {
        ApiError::Config(
            "LASTRO_CORS_ALLOWED_ORIGINS must list http(s) origins without paths".into(),
        )
    };
    value
        .split(',')
        .map(str::trim)
        .filter(|origin| !origin.is_empty())
        .map(|origin| {
            let url = reqwest::Url::parse(origin).map_err(|_| invalid())?;
            if !matches!(url.scheme(), "http" | "https")
                || url.host_str().is_none()
                || url.path() != "/"
                || origin.ends_with('/')
                || url.query().is_some()
                || url.fragment().is_some()
            {
                return Err(invalid());
            }
            HeaderValue::from_str(origin).map_err(|_| invalid())
        })
        .collect()
}
